_icon_cache = {}

def get_icon(name: str, color: str = '#f4f4f6', size: int = 18) -> QIcon:
    """
    Renders vector SVG icons from public library (Lucide / Fluent) with anti-aliasing.
    """
    cache_key = f"{name}_{color}_{size}"
    if cache_key in _icon_cache:
        return _icon_cache[cache_key]

    raw_svg = SVGS.get(name)
    if not raw_svg:
        return QIcon()

    svg_content = raw_svg.replace('{color}', color)
    renderer = QSvgRenderer(QByteArray(svg_content.encode('utf-8')))

    pix = QPixmap(size, size)
    pix.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pix)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter)
    painter.end()

    icon = QIcon(pix)
    _icon_cache[cache_key] = icon
    return icon
